-- Seed Data for Smart Inventory System
USE smart_inventory;

-- 1. Users (password for both is 'password')
ON DUPLICATE KEY UPDATE username = VALUES(username);

-- 2. Suppliers
ON DUPLICATE KEY UPDATE name = VALUES(name);

-- 3. Products
ON DUPLICATE KEY UPDATE stock = VALUES(stock), reorder_point = VALUES(reorder_point);

-- 4. Stock Movements (last 90 days of IN and OUT movements)

-- 5. Sample Purchase Orders

-- 6. Sample Forecasts (historical for MAPE validation + forward 14 days)
ON DUPLICATE KEY UPDATE predicted_qty = VALUES(predicted_qty);